verjaehrung_hoehere_gewalt_festes_ablauffenster <- function(fristlauf_erster_tag=NULL, fristende_ohne_diese_hemmung=NULL, verhinderungszeitraeume=NULL, fenstermodell=NULL, monatsendregel=NULL, methodennachweis=NULL) {
 a <- .datum(fristlauf_erster_tag,'fristlauf_erster_tag');e <- .datum(fristende_ohne_diese_hemmung,'fristende_ohne_diese_hemmung');.auswahl(fenstermodell,'fenstermodell',c('fester_ablauf_ohne_206'));.text(methodennachweis,'methodennachweis')
 if(a>e) .fehler('fristlauf','Erster Fristtag liegt nach Ausgangsende.')
 g <- rueckwaertsfrist_kalendergrenze(fristende_ohne_diese_hemmung,6,'monate','tagesende',monatsendregel,methodennachweis)$wert$grenztag_beginn
 von <- format(max(a,.datum(g,'fensterbeginn')),'%Y-%m-%d')
 r <- verjaehrung_hoehere_gewalt_fenster(fristlauf_erster_tag,fristende_ohne_diese_hemmung,von,fristende_ohne_diese_hemmung,verhinderungszeitraeume,methodennachweis)$wert
 wert <- list(fenster_erster_tag=von,fenster_letzter_tag=fristende_ohne_diese_hemmung,rechnerischer_letzter_tag=r$rechnerischer_letzter_tag,beruecksichtigte_hemmungstage=r$beruecksichtigte_hemmungstage)
 eingaben <- list(fristlauf_erster_tag=fristlauf_erster_tag, fristende_ohne_diese_hemmung=fristende_ohne_diese_hemmung, verhinderungszeitraeume=verhinderungszeitraeume, fenstermodell=fenstermodell, monatsendregel=monatsendregel, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"daten_und_tage","BGB_VERJAEHRUNG_HOEHERE_GEWALT_FESTES_ABLAUFFENSTER",eingaben,list(list(operation="Festes rechtlich ausgew\u00e4hltes Sechsmonatsfenster aus Ausgangsablauf berechnen, auf tats\u00e4chlichen Fristlauf begrenzen und bestehende206/209-Schnittmengenrechnung anwenden.")),eingaben)
 ergebnis$hinweise <- list("Bedingte vollst\u00e4ndige206-Fensterarithmetik f\u00fcr das ausdr\u00fccklich gew\u00e4hlte feste Ablaufmodell. Sechs Kalendermonate vom Tagesende der Ausgangsfrist r\u00fcckw\u00e4rts, Fensterbeginn ist Grenztagesbeginn, fr\u00fchestens erster Fristlauftag. Verhinderungsintervalle schneiden, \u00dcberschneidungen vereinigen und209-Tage fortschreiben. Kein vom Nutzer vorberechneter Fensterbeginn erforderlich. LGRegensburg18.6.2026,45O1916/24,Rn35\u201337 st\u00fctzt im dortigen Fall Begrenzung auf festen Zeitraum bis zum Ablauf ohne206; keine Behauptung h\u00f6chstrichterlicher oder universeller Freigabe. Keine automatische dynamische Fensterverschiebung; deren urspr\u00fcngliche Inventarbezeichnung war eine offene Hypothese, kein belegter gesetzlicher Algorithmus. Hindernisse au\u00dferhalb des festen Fensters werden in diesem Modell nicht erfasst. Ein fortdauerndes Hindernis ohne rechtlich feststehendes Ende erlaubt keinen endg\u00fcltigen Ablauf. Weitere Hemmungen nicht doppelt z\u00e4hlen;210/211,Neubeginn und gegebenenfalls193 anschlie\u00dfend gesondert qualifizieren.")
 ergebnis
}
